static uint32_t rd32(uint32_t a)
{
	return *(volatile uint32_t *)a;
}

static uint32_t rd16(uint32_t a)
{
	return *(volatile uint16_t *)a;
}

static void wr32(uint32_t a, uint32_t v)
{
	*(volatile uint32_t *)a = v;
}

static bool sim_consistent(void);

uint32_t c_OlyTaskSleep(void)
{
	if (sim.watch) {
		sim.yields++;
		if (!sim_consistent())
			sim.window_bad++;
	}
	return 0;
}

uint32_t c_dcache_flush_all(void)
{
	if (!sim.watch)
		return 0;
	sim.flushes++;
	if (!sim_consistent())
		sim.window_bad++;
	if (sim.flushes == sim.corrupt_at)
		wr32(FW_CUSTOM_TAB_LIST, 0x000D0000u);
	return 0;
}

/* The picker the stock constructor leaves for 0x115: stock handlers, stock init run (5 entries),
   both flags set. */
uint32_t c_menu_picker_create(void)
{
	const uint32_t *key = (const uint32_t *)mreg[0];

	sim.key_id = key[0];
	sim.key_kind = mreg[2];
	sim.creates++;
	sim.style_at_create = rd32(SIM_STYLE79);
	memset(sim_pk, 0, sizeof(sim_pk));
	for (unsigned int i = 0; i < SIM_PK_STOCK_N; i++) {
		sim_vals[i] = (uint32_t)i - 2u;
		sim_dis[i] = 0;
	}
	sim_pk[0x48 / 4] = sim.pk_foreign ? 0x609E0001u : FW_MENU_PICKER_STOCK_FN;
	*(uint16_t *)((uint8_t *)sim_pk + 0x50) = (uint16_t)key[0];
	*(uint16_t *)((uint8_t *)sim_pk + 0x54) = sim.pk_small ? 1 : SIM_PK_STOCK_N;
	*(uint16_t *)((uint8_t *)sim_pk + 0x56) = 2;
	sim_pk[0x5C / 4] = (uint32_t)sim_dis;
	sim_pk[0x60 / 4] = (uint32_t)sim_vals;
	sim_pk[0x64 / 4] = 1;
	sim_pk[0x6C / 4] = 4;
	sim_pk[0x80 / 4] = 1;
	return (uint32_t)sim_pk;
}

/* scheap: one 128-byte block per call from a small pool, NULL at the call malloc_fail_at. */
uint32_t c_malloc(void)
{
	sim.mallocs++;
	if (sim.mallocs == sim.malloc_fail_at || sim.mallocs > SIM_HEAP || mreg[2] > 128)
		return 0;
	return (uint32_t)sim_heap[sim.mallocs - 1u];
}

uint32_t c_free(void)
{
	if (sim.frees < 8)
		sim.freed[sim.frees] = mreg[0];
	sim.frees++;
	return 0;
}

/* No USB cable, the card mounted: the saved state's card gate is open. */
uint32_t c_ui_key_get_state(void)
{
	return 1;
}

uint32_t c_fileif_get_media_status(void)
{
	return 0x100;
}

/* The stock picker handler(picker@A0, code@D0, param@D1): MENU closes the list (3). */
uint32_t c_picker_stock(void)
{
	sim.stock_calls++;
	sim.stock_pk = mreg[0];
	sim.stock_code = mreg[2];
	return mreg[2] == 0x900E ? 3 : 1;
}

/* --- the firmware model --- */

static unsigned int sim_count(const struct sim_pair *p)
{
	return p->half ? rd32(p->count) >> 16 : rd32(p->count);
}

/* No count exceeds the table its pointer holds; the tab is listed only when every other pair
   points at our tables. */
static bool sim_consistent(void)
{
	bool all_ours = true;

	for (unsigned int i = 0; i < SIM_NPAIRS; i++) {
		const struct sim_pair *p = &sim_pairs[i];
		bool stock = rd32(p->ptr) == p->stock;

		if (sim_count(p) > (stock ? p->stock_n : p->ours_n))
			return false;
		if (i && stock)
			all_ours = false;
	}
	if (rd32(FW_CUSTOM_TAB_LIST) >> 16 == 12 && rd32(FW_CUSTOM_TAB_LIST + 4u) != 0x60D33E9Eu)
		return all_ours && rd32(FW_CUSTOM_TAB_REC_L + 4u) == 5u &&
		       rd32(SIM_STYLE79) == 0x00010000u + SIM_OPT0 &&
		       rd32(FW_GUI_IMAGE_2043) != SIM_ICON_STOCK &&
		       rd32(FW_GUI_IMAGE_2040) != SIM_ICON_DIM_STOCK;
	return true;
}

static uint32_t sim_tabrec(unsigned int tab)
{
	for (unsigned int i = 0; i < 14; i++)
		if (rd16(SIM_TABREC + 20u * i) == tab)
			return SIM_TABREC + 20u * i;
	return 0;
}

static uint32_t sim_row(unsigned int id)
{
	uint32_t rec = sim_tabrec(SIM_TAB), rows = rd32(rec + 0xCu);

	for (unsigned int i = 0; i < rd16(rec + 2u); i++)
		if (rd16(rows + 36u * i) == id)
			return rows + 36u * i;
	return 0;
}

/* A 12-byte label cell by value: its kind | lang << 16 word, text in *text; 0 if none. */
static uint32_t sim_label(uint32_t table, unsigned int n, uint32_t value, const char **text)
{
	for (unsigned int i = 0; i < n; i++) {
		uint32_t e = table + 12u * i;

		if (rd32(e) != value)
			continue;
		*text = (const char *)rd32(e + 8u);
		return rd32(e + 4u);
	}
	return 0;
}

/* The value column of row id: the cell matching 0 (the controller's get of a fresh id). */
static uint32_t sim_value(unsigned int id, const char **text)
{
	uint32_t row = sim_row(id);

	return row ? sim_label(rd32(row + 0x18u), rd16(row + 2u), 0, text) : 0;
}

static unsigned int sim_style(unsigned int id)
{
	for (unsigned int i = 0; i < 0x50; i++)
		if (rd16(FW_CUSTOM_ROW_STYLES + 4u * i) == id)
			return rd16(FW_CUSTOM_ROW_STYLES + 4u * i + 2u);
	return 0xFFFF;
}

/* The L1 callback of row id, 0 if none. */
static uint32_t sim_l1(unsigned int id)
{
	uint32_t t = rd32(FW_CUSTOM_TAB_CFG_L + 0xCu);

	for (unsigned int i = 0; i < rd32(FW_CUSTOM_TAB_CFG_L + 0x10u); i++)
		if (rd16(t + 12u * i + 4u) == id)
			return rd32(t + 12u * i + 8u);
	return 0;
}

static bool sim_streq(const char *a, const char *b)
{
	while (*a && *a == *b)
		a++, b++;
	return *a == *b;
}

static bool sim_text(uint32_t desc, const char *text, const char *want)
{
	return (desc & 0xFFFFu) == 5u && text && sim_streq(text, want);
}

/* Image table word w points, uncached, at an 8-bpp 38 x 40 record whose uncached bitmap holds
   bits (bytes long, size in the record). */
static bool sim_icon(uint32_t w, const uint32_t *bits, uint32_t size, uint32_t bytes)
{
	uint32_t rec = rd32(w), bmp = rd32(rec + 0x10u);

	return rec >> 28 == 0xA && rd16(rec) == 0x0E && rd16(rec + 2u) == 38 &&
	       rd16(rec + 4u) == 40 && rd16(rec + 6u) == 8 && !rd32(rec + 8u) &&
	       rd32(rec + 0xCu) == size && !rd32(rec + 0x14u) && bmp >> 28 == 0xA &&
	       rd32(bmp) == 0x03025027u && !memcmp((const void *)bmp, bits, bytes);
}

/* --- setup --- */

static void sim_stock(void)
{
	for (unsigned int i = 0; i < sim_image_n; i++)
		memcpy((void *)sim_image[i].addr, sim_image[i].bytes, sim_image[i].len);
}

static bool sim_is_stock(void)
{
	for (unsigned int i = 0; i < sim_image_n; i++)
		if (memcmp((const void *)sim_image[i].addr, sim_image[i].bytes, sim_image[i].len))
			return false;
	return true;
}

/* A fresh boot: stock bytes, no menu tree, nothing installed. */
static void sim_boot(void)
{
	sim_stock();
	memset(&fui, 0, sizeof(fui));
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x0F;
	*(volatile uint8_t *)FW_GUI_SUPER = 1;
}

/* --- checks --- */

static void check_limits(void)
{
	static const char *const six[] = { "a", "b", "c", "d", "e", "f" };
	static int32_t v;
	static const struct fenykl_cfg_group g = { "G", 1 };
	static const struct fenykl_cfg_opt bad[] = {
		{ .name = "x.i", .label = "Int", .group = &g, .value = &v, .max = 9,
		  .type = FENYKL_CFG_INT },
		{ .name = "x.e", .label = "Six", .group = &g, .value = &v, .max = 5, .names = six,
		  .type = FENYKL_CFG_ENUM },
		{ .name = "x.l", .label = "A label of more than thirty-two chars", .group = &g,
		  .value = &v, .max = 1, .type = FENYKL_CFG_BOOL },
		{ .name = "x.b", .label = "Ok", .group = &g, .value = &v, .max = 1,
		  .type = FENYKL_CFG_BOOL },
	};
	struct fenykl_cfg_opt many[FENYKL_UI_OPTS_MAX + 1];
	static const char *n26[FENYKL_UI_VALUES_MAX];

	for (unsigned int i = 0; i < 3; i++)
		CHECK(1 + i, fui_collect(&bad[i], &bad[4]) == FENYKL_UI_EOPTS);
	CHECK(4, fui_collect(&bad[3], &bad[4]) == 0 && fui.nopts == 1);
	for (unsigned int i = 0; i <= FENYKL_UI_OPTS_MAX; i++)
		many[i] = bad[3];
	CHECK(5, fui_collect(many, many + FENYKL_UI_OPTS_MAX + 1) == FENYKL_UI_EOPTS);
	CHECK(6, fui_collect(many, many + FENYKL_UI_OPTS_MAX) == 0);
	CHECK(7, fui_collect(&bad[3], &bad[3]) == FENYKL_UI_EOPTS);
	/* 26 names each: four fit the cells, five do not */
	for (unsigned int i = 0; i < FENYKL_UI_VALUES_MAX; i++)
		n26[i] = "n";
	for (unsigned int i = 0; i < 5; i++)
		many[i] = (struct fenykl_cfg_opt){ .name = "x.n", .label = "N", .group = &g,
						   .value = &v, .max = 25, .names = n26,
						   .type = FENYKL_CFG_ENUM };
	CHECK(8, fui_collect(many, many + 4) == 0 && fui.nopts == 4);
	CHECK(9, fui_collect(many, many + 5) == FENYKL_UI_EOPTS);
}

static void check_start(void)
{
	sim_boot();
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x07;
	CHECK(10, fenykl_ui_install() == FENYKL_UI_EAGAIN);
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x0F;
	*(volatile uint8_t *)FW_GUI_SUPER = 0x11;
	CHECK(11, fenykl_ui_install() == FENYKL_UI_EAGAIN);
	*(volatile uint8_t *)FW_GUI_SUPER = 1;
	/* the shared style entry, a donor word, a copied list that differ: nothing written */
	wr32(SIM_STYLE79, 0x00010333u);
	CHECK(12, fenykl_ui_install() == FENYKL_UI_ESTOCK);
	sim_stock();
	wr32(FW_MENU_PICKER_HANDLERS + 0x18u, 0x609EF618u);
	CHECK(13, fenykl_ui_install() == FENYKL_UI_ESTOCK);
	sim_stock();
	*(volatile uint16_t *)(0x60D33E9Eu + 2u * 4u) = SIM_TAB;
	CHECK(14, fenykl_ui_install() == FENYKL_UI_ESTOCK);
	sim_stock();
	*(volatile uint16_t *)(FW_CUSTOM_ROW_STYLES + 4u * 3u) = SIM_OPT0 + 4u;
	CHECK(15, fenykl_ui_install() == FENYKL_UI_ESTOCK);
	sim_stock();
	CHECK(16, sim_is_stock() && !fui.installed);
	/* an image record word that is not stock: refused before any store */
	wr32(FW_GUI_IMAGE_2040, SIM_ICON_DIM_STOCK + 0x10u);
	CHECK(17, fenykl_ui_install() == FENYKL_UI_ESTOCK && !fui.installed);
	wr32(FW_GUI_IMAGE_2040, SIM_ICON_DIM_STOCK);
	CHECK(18, sim_is_stock());
}

static void check_install(void)
{
	const char *text = NULL;
	uint32_t rec, row, d;

	sim.watch = true;
	sim.flushes = 0;
	sim.yields = 0;
	sim.window_bad = 0;
	CHECK(20, fenykl_ui_install() == 0 && fui.installed && fui.done == SIM_WORDS);
	sim.watch = false;
	CHECK(21, sim.flushes >= 2 * SIM_WORDS && sim.window_bad == 0 && sim.yields == 2);
	CHECK(22, fenykl_ui_install() == FENYKL_UI_EBUSY && fui.st.late == 0);
	/* tab list: A..K, then L */
	d = rd32(FW_CUSTOM_TAB_LIST + 4u);
	CHECK(23, rd32(FW_CUSTOM_TAB_LIST) >> 16 == 12 && rd16(d + 22u) == SIM_TAB &&
		  !memcmp((const void *)d, (const void *)0x60D33E9Eu, 22));
	/* tab record: info row + 11 options, kind-5 title; row list in the same order */
	rec = sim_tabrec(SIM_TAB);
	d = rd32(FW_CUSTOM_ROWS_L + 4u);
	CHECK(24, rec == FW_CUSTOM_TAB_REC_L && rd16(rec + 2u) == 12 && rd16(rec + 4u) == 5 &&
		  sim_streq((const char *)rd32(rec + 8u), "L. Fenykl") &&
		  rd32(FW_CUSTOM_ROWS_L) == 0x000C0000u && rd16(d) == SIM_INFO &&
		  rd16(d + 22u) == SIM_OPT0 + 10u && rd16(FW_CUSTOM_TAB_ICON_L + 6u) == 0xB);
	/* info row: value "Loaded", no options, no style; RIGHT and OK swallowed */
	row = sim_row(SIM_INFO);
	CHECK(25, row && !rd32(row + 4u) && !rd32(row + 0x20u) &&
		  sim_text(rd32(row + 8u), (const char *)rd32(row + 12u), "Fenykl") &&
		  sim_text(sim_value(SIM_INFO, &text), text, "Loaded") &&
		  sim_style(SIM_INFO) == 0xFFFF && !sim_l1(SIM_INFO));
	d = rd32(FW_CUSTOM_TAB_CFG_L + 0x14u);
	CHECK(26, rd32(FW_CUSTOM_TAB_CFG_L + 0x18u) == 2 && rd32(d) == 1 &&
		  rd16(d + 4u) == SIM_INFO && rd16(d + 24u + 4u) == SIM_INFO &&
		  fw_call_menu_row(rd32(d + 8u), sim_sub) == 1);
	d = rd32(FW_CUSTOM_TAB_CFG_L + 0x1Cu);
	CHECK(27, rd16(d + 4u) == SIM_INFO && fw_call_menu_row(rd32(d + 8u), sim_sub) == 1 &&
		  sim.creates == 0);
	/* options sorted by group order: First, Many (link order), System */
	row = sim_row(SIM_OPT0);
	CHECK(28, sim_text(rd32(row + 8u), (const char *)rd32(row + 12u), "First row") &&
		  sim_text(rd32(row + 0x10u), (const char *)rd32(row + 0x14u), "First") &&
		  sim_value(SIM_OPT0, &text) == SIM_ON && rd32(row + 4u) == 2 &&
		  sim_label(rd32(row + 0x20u), 2, 0, &text) == SIM_OFF);
	row = sim_row(SIM_OPT0 + 1u);
	CHECK(29, sim_text(rd32(row + 8u), (const char *)rd32(row + 12u), "Row zero") &&
		  sim_value(SIM_OPT0 + 1u, &text) == SIM_OFF);
	row = sim_row(SIM_OPT0 + 10u);
	CHECK(30, sim_text(rd32(row + 8u), (const char *)rd32(row + 12u), "Log level") &&
		  rd32(row + 4u) == 4 && sim_text(sim_value(SIM_OPT0 + 10u, &text), text, "info") &&
		  sim_text(sim_label(rd32(row + 0x20u), 4, 3, &text), text, "debug"));
	/* every option row its own L1 callback; entry 79 keyed to the first, the stock styles kept */
	for (unsigned int i = 0; i < SIM_NOPTS; i++)
		CHECK(31, sim_l1(SIM_OPT0 + i) &&
			  (!i || sim_l1(SIM_OPT0 + i) != sim_l1(SIM_OPT0 + i - 1u)));
	CHECK(32, sim_style(SIM_OPT0) == 1 && sim_style(SIM_OPT0 + 1u) == 0xFFFF &&
		  sim_style(0x28C) == 4 && sim_style(0xA7) == 5);
	/* letter list: title, help and open records of L */
	d = sim_label(rd32(FW_CUSTOM_LETTER_PAGE + 4u), rd16(FW_CUSTOM_LETTER_PAGE + 2u), SIM_TAB,
		      &text);
	CHECK(33, rd16(FW_CUSTOM_LETTER_PAGE + 2u) == 12 && sim_text(d, text, "Fenykl") &&
		  sim_label(rd32(FW_CUSTOM_LETTER_PAGE + 4u), 12, 0x846, &text) == 0x00300004u);
	d = rd32(FW_CUSTOM_LETTER_CFG + 0x1Cu) + 24u * 11u;
	CHECK(34, rd32(FW_CUSTOM_LETTER_CFG + 0x20u) == 12 &&
		  rd32(FW_CUSTOM_LETTER_CFG + 0x18u) == 12 && rd32(d) == 1 &&
		  rd16(d + 4u) == SIM_TAB && !rd32(d + 8u) && rd32(d + 12u) == 0xF &&
		  rd32(d + 16u) == 1 &&
		  !memcmp((const void *)rd32(FW_CUSTOM_LETTER_CFG + 0x14u), (const void *)0x60D2E2ACu,
			  264));
	CHECK(35, sim_icon(FW_GUI_IMAGE_2043, fui_icon_bright, FUI_ICON_BRIGHT_SIZE,
			   sizeof(fui_icon_bright)));
	CHECK(36, sim_icon(FW_GUI_IMAGE_2040, fui_icon_dim, FUI_ICON_DIM_SIZE,
			   sizeof(fui_icon_dim)));
}

static void check_rows(void)
{
	const char *text = NULL;
	uint32_t pk = (uint32_t)sim_pk;

	/* the first option: a picker with Off/On on its value On */
	fw_call_menu_row(sim_l1(SIM_OPT0), sim_sub);
	CHECK(40, sim.creates == 1 && sim.key_id == 0x115 && sim.key_kind == 0 &&
		  sim_sub[0x58 / 4] == pk && sim_sub[0x50 / 4] == 0 &&
		  sim.style_at_create == 0x00010000u + SIM_OPT0);
	CHECK(41, sim_pk[0x48 / 4] != FW_MENU_PICKER_STOCK_FN && sim_pk[0x2C / 4] &&
		  !sim_pk[0x64 / 4] && !sim_pk[0x80 / 4]);
	CHECK(42, rd16(pk + 0x54) == 2 && rd16(pk + 0x56) == 1 && sim_vals[0] == 0 &&
		  sim_vals[1] == 1 && sim_pk[0x68 / 4] == 0 && sim_pk[0x6C / 4] == 1);
	/* OK on Off: cfg set, value cell Off, no stock call */
	*(uint16_t *)(pk + 0x56) = 0;
	CHECK(43, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900C, 0) == 2 && first == 0 &&
		  sim_value(SIM_OPT0, &text) == SIM_OFF && fui.st.sets == 1 && !sim.stock_calls);
	/* MENU goes to the stock handler */
	CHECK(44, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900E, 0) == 3 &&
		  sim.stock_calls == 1 && sim.stock_pk == pk && sim.stock_code == 0x900E);
	/* the ENUM: four names, cursor on info; OK on debug runs on_change in the caller */
	fw_call_menu_row(sim_l1(SIM_OPT0 + 10u), sim_sub);
	CHECK(45, rd16(pk + 0x54) == 4 && rd16(pk + 0x56) == 2 && sim_pk[0x6C / 4] == 3 &&
		  sim.style_at_create == 0x00010000u + SIM_OPT0 + 10u &&
		  sim_style(SIM_OPT0 + 10u) == 1 && sim_style(SIM_OPT0) == 0xFFFF && !sim.mallocs);
	*(uint16_t *)(pk + 0x56) = 3;
	sim.changes = 0;
	CHECK(46, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x972B, 0) == 2 && level == 3 &&
		  sim.changes == 1 && sim_text(sim_value(SIM_OPT0 + 10u, &text), text, "debug"));
	/* the init after the set puts the cursor on the value */
	*(uint16_t *)(pk + 0x56) = 0;
	fw_call_menu_row(sim_pk[0x2C / 4], sim_pk);
	CHECK(47, rd16(pk + 0x56) == 3);
	/* an OK past the entries, or on a picker that is not ours, sets nothing */
	*(uint16_t *)(pk + 0x56) = 4;
	CHECK(48, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900C, 0) == 2 && level == 3);
	CHECK(49, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk + 1, 0x900C, 0) == 2 &&
		  fui.st.sets == 2 && fui.st.refused == 2);
	/* a picker with a foreign handler is left as it is, and still handed over */
	sim.pk_foreign = true;
	fw_call_menu_row(sim_l1(SIM_OPT0 + 1u), sim_sub);
	sim.pk_foreign = false;
	CHECK(50, sim_pk[0x48 / 4] == 0x609E0001u && !sim_pk[0x2C / 4] && sim_pk[0x64 / 4] &&
		  rd16(pk + 0x54) == SIM_PK_STOCK_N && sim_sub[0x58 / 4] == pk &&
		  fui.st.refused == 3 && fui.st.opens == 2);
	/* seven names on the donor's five entries: both arrays replaced, the stock ones freed */
	fw_call_menu_row(sim_l1(SIM_OPT0 + 9u), sim_sub);
	CHECK(54, sim.mallocs == 2 && sim.frees == 2 && sim.freed[0] == (uint32_t)sim_dis &&
		  sim.freed[1] == (uint32_t)sim_vals && sim_pk[0x5C / 4] == (uint32_t)sim_heap[0] &&
		  sim_pk[0x60 / 4] == (uint32_t)sim_heap[1] && rd16(pk + 0x54) == 7 &&
		  sim_heap[1][6] == 6 && sim_pk[0x6C / 4] == 6 && fui.st.reallocs == 1 &&
		  sim_pk[0x48 / 4] != FW_MENU_PICKER_STOCK_FN && fui.st.opens == 3);
	*(uint16_t *)(pk + 0x56) = 6;
	CHECK(55, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900C, 0) == 2 && m8 == 6 &&
		  fui.st.sets == 3);
	/* no memory for the second array: the first freed, the stock arrays kept, every event
	   cancels, nothing is set */
	sim.pk_small = true;
	sim.malloc_fail_at = sim.mallocs + 2u;
	fw_call_menu_row(sim_l1(SIM_OPT0 + 10u), sim_sub);
	sim.pk_small = false;
	CHECK(53, sim_pk[0x48 / 4] != FW_MENU_PICKER_STOCK_FN && !sim_pk[0x2C / 4] &&
		  rd16(pk + 0x54) == 1 && sim_pk[0x5C / 4] == (uint32_t)sim_dis &&
		  sim.frees == 3 && sim.freed[2] == (uint32_t)sim_heap[2] &&
		  fui.st.refused == 4 && fui.st.opens == 3 && fui.st.reallocs == 1 &&
		  rd32(SIM_STYLE79) == 0x00010000u + SIM_OPT0 + 10u &&
		  fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900C, 0) == 3 && level == 3 &&
		  fui.st.sets == 3 && sim.stock_calls == 1);
	/* a value changed outside the lists (a late cfg load): the tick rewrites its cell */
	m5 = 1;
	level = 0;
	fenykl_ui_tick();
	CHECK(51, sim_value(SIM_OPT0 + 6u, &text) == SIM_ON && fui.st.refreshes == 2 &&
		  sim_text(sim_value(SIM_OPT0 + 10u, &text), text, "err"));
	fenykl_ui_tick();
	CHECK(52, fui.st.refreshes == 2 && fui.st.cpu1_actions == 0);
}

/* Entry 79 holds the last opened row's key: the removal still restores every stock byte. */
static void check_remove(void)
{
	uint32_t stale = sim_l1(SIM_OPT0 + 1u);

	*(volatile uint8_t *)FW_GUI_SUPER = 0x11;
	CHECK(70, fenykl_ui_remove() == FENYKL_UI_EAGAIN && fui.installed);
	*(volatile uint8_t *)FW_GUI_SUPER = 1;
	CHECK(71, rd32(SIM_STYLE79) != 0x00010000u + SIM_OPT0 && fenykl_ui_remove() == 0 &&
		  !fui.installed && sim_is_stock());
	CHECK(75, rd32(FW_GUI_IMAGE_2043) == SIM_ICON_STOCK &&
		  rd32(FW_GUI_IMAGE_2040) == SIM_ICON_DIM_STOCK);
	CHECK(72, fenykl_ui_remove() == FENYKL_UI_ENOTINST);
	/* a stale page actuator's open leaves the restored entry stock */
	fw_call_menu_row(stale, sim_sub);
	CHECK(74, rd32(SIM_STYLE79) == 0x0001028Cu);
	/* installed again on the same boot */
	CHECK(73, fenykl_ui_install() == 0 && rd32(SIM_STYLE79) == 0x00010000u + SIM_OPT0);
}

/* The full tab: 40 rows with a 26-name ENUM; the last row keys entry 79 to 0xF68. */
static void check_full(void)
{
	static int32_t v[FENYKL_UI_OPTS_MAX];
	static const char *names[FENYKL_UI_VALUES_MAX];
	static const struct fenykl_cfg_group g = { "Page", 1 };
	static struct fenykl_cfg_opt full[FENYKL_UI_OPTS_MAX];
	uint32_t pk = (uint32_t)sim_pk;
	unsigned int mallocs;

	for (unsigned int i = 0; i < FENYKL_UI_VALUES_MAX; i++)
		names[i] = "n";
	for (unsigned int i = 0; i < FENYKL_UI_OPTS_MAX; i++)
		full[i] = (struct fenykl_cfg_opt){ .name = "f", .label = "Row", .group = &g,
						   .value = &v[i], .max = 1,
						   .type = FENYKL_CFG_BOOL };
	full[23].max = FENYKL_UI_VALUES_MAX - 1;
	full[23].names = names;
	full[23].type = FENYKL_CFG_ENUM;
	sim_boot();
	CHECK(90, fenykl_ui_install_opts(full, full + FENYKL_UI_OPTS_MAX) == 0 &&
		  rd16(FW_CUSTOM_TAB_REC_L + 2u) == FENYKL_UI_OPTS_MAX + 1u &&
		  rd32(FW_CUSTOM_ROWS_L) >> 16 == FENYKL_UI_OPTS_MAX + 1u);
	fw_call_menu_row(sim_l1(SIM_OPT0 + FENYKL_UI_OPTS_MAX - 1u), sim_sub);
	CHECK(91, sim.style_at_create == 0x00010F68u && rd16(pk + 0x54) == 2);
	mallocs = sim.mallocs;
	fw_call_menu_row(sim_l1(SIM_OPT0 + 23u), sim_sub);
	CHECK(92, sim.style_at_create == 0x00010F58u && sim.mallocs == mallocs + 2u &&
		  rd16(pk + 0x54) == 26 && sim_pk[0x6C / 4] == 25 &&
		  ((uint32_t *)sim_pk[0x60 / 4])[25] == 25 && fui.st.reallocs == 1);
	CHECK(93, fenykl_ui_remove() == 0 && sim_is_stock());
}

/* A table outside cfg's: the set stores the value and calls on_change, cfg is not asked. */
static void check_ram(void)
{
	static int32_t v;
	static const struct fenykl_cfg_group g = { "RAM", 1 };
	static const struct fenykl_cfg_opt ram[] = {
		{ .name = "r.0", .label = "RAM row", .group = &g, .value = &v, .max = 1,
		  .on_change = sim_changed, .type = FENYKL_CFG_BOOL },
	};
	uint32_t pk = (uint32_t)sim_pk;

	sim_boot();
	sim.changes = 0;
	CHECK(80, fenykl_ui_install_opts(ram, ram + 1) == 0 && fui.nopts == 1);
	fw_call_menu_row(sim_l1(SIM_OPT0), sim_sub);
	*(uint16_t *)(pk + 0x56) = 1;
	CHECK(81, fw_call_menu_picker(sim_pk[0x48 / 4], sim_pk, 0x900C, 0) == 2 && v == 1 &&
		  sim.changes == 1 && fui.st.sets == 1 && fui.st.set_fail == 0);
}

static void check_late(void)
{
	/* a menu tree built before the install: installed, counted */
	sim_boot();
	wr32(FW_CUSTOM_TAB_OBJ, (uint32_t)sim_obj);
	CHECK(60, fenykl_ui_install() == 0 && fui.st.late == 1);
	/* the tab list count changes during the install: rolled back, that word left */
	sim_boot();
	sim.watch = true;
	sim.flushes = 0;
	sim.corrupt_at = 2u * (SIM_WORDS - 2u) + 2u;	/* the flush before the tab list pointer */
	CHECK(61, fenykl_ui_install() == FENYKL_UI_ESTOCK && !fui.installed);
	sim.watch = false;
	sim.corrupt_at = 0;
	CHECK(62, rd32(FW_CUSTOM_TAB_LIST) == 0x000D0000u);
	wr32(FW_CUSTOM_TAB_LIST, 0x000B0000u);
	CHECK(63, sim_is_stock());
}

void plugin_main(uint32_t load_base, uint32_t image_size)
{
	(void)load_base;
	(void)image_size;
	check_limits();
	check_start();
	check_install();
	check_rows();
	check_remove();
	check_late();
	check_ram();
	check_full();
	sim_exit_code = sim.first_fail;
}
